PLAN = {"task_name": "t", "segments": [{"type": "navigation", "description": "Go to the bench", "completion_criteria": "There", "target": "bench", "primitive": None, "objects": None},
                                       {"type": "manipulation", "description": "Pick up the beaker", "completion_criteria": "The beaker is held", "target": None, "primitive": "pick", "objects": [{"phrase": "the beaker", "role": "manipulated"}]}]}


class Resp:
    def __init__(self, text):
        self.text, self.candidates = text, None


class FakeClient:
    """A client whose generate_content plays a list of outcomes (an exception is raised, a string is the reply text)."""

    def __init__(self, outcomes):
        self.outcomes, self.calls, self.models = list(outcomes), [], self

    def generate_content(self, model, contents, config):
        self.calls.append({"model": model, "contents": contents, "config": config})
        o = self.outcomes.pop(0) if len(self.outcomes) > 1 else self.outcomes[0]
        if isinstance(o, Exception):
            raise o
        return Resp(o)


def api_error(code, text="x"):
    cls = errors.ClientError if code < 500 else errors.ServerError
    return cls(code, {"error": {"code": code, "message": text, "status": "S"}})


def caller(outcomes, mode="cache_or_live", cache_dir=None, sleeps=None, cfg=LLM_CFG):
    d = cache_dir or tempfile.mkdtemp(prefix="llm_cache_test_")
    sleeps = sleeps if sleeps is not None else []
    return GeminiCaller(cfg, mode, FakeClient(outcomes), LLMCache(d), say=lambda *_: None, sleep=sleeps.append), d


def raises(fn, cls, text=""):
    try:
        fn()
    except cls as e:
        return text in str(e)
    return False


